    public static PathIcon Make(string data, double size = 16, IBrush brush = null)
    {
        var icon = new PathIcon
        {
            Data = Geometry.Parse(data),
            Width = size,
            Height = size,
            VerticalAlignment = VerticalAlignment.Center,
        };
        if (brush != null) icon.Foreground = brush;
        return icon;
    }
